mod arena;
mod body;
mod borrow;
mod cache;
mod db;
mod config;
// The DB backend: rusqlite by default, turso under `--features turso`. The
// turso file is mounted under the same `cursor` name so the rest of the host
// (effect executor, ctx sweep) is unchanged.
#[cfg(not(feature = "turso"))]
mod cursor;
#[cfg(feature = "turso")]
#[path = "turso_db.rs"]
mod cursor;
mod effect;
mod effects;
mod middleware;
mod profile;
mod roc_call;
mod router;
mod server;
// The analysis shadow is ALWAYS rusqlite (turso has no authorizer); it
// derives cache deps for whichever engine `cursor` is.
mod shadow;
